   "sides": false,
   "feel": "Cijeli prednji trbušni zid, posebno donji dio",
   "steps": [
    "Lezi na leđa s ispruženim nogama i rukama ispruženima iznad glave.",
    "Utisni donja leđa u podlogu tako da između leđa i poda ne ostane razmak.",
    "Podigni spojene ispružene noge 15–30° od poda.",
    "Istovremeno podigni glavu, ramena i ruke tako da lopatice budu tik iznad poda, a ruke u produžetku tijela.",
    "Drži položaj banane, u kojem su na podu samo donja leđa i stražnjica, i diši mirno.",
    "Na kraju polako spusti noge, ramena i glavu na pod."
   ],
   "mistakes": [
    "Donja leđa se odvajaju od poda – podigni noge više ili savij koljena.",
    "Vrat se napinje i brada strši naprijed – lagano uvuci bradu i gledaj prema stopalima.",
    "Zadržavaš dah – diši kratko, ali bez otpuštanja trbuha.",
    "Ruke padaju na pod iza glave – drži ih podignutima ili ih stavi uz tijelo dok ne ojačaš."
   ],
   "note": "Hollow hold uči te zaključati rebra i zdjelicu dok su ruke i noge daleko od tijela, a isti zadatak trup ima u sprintu i skoku. Uvrsti ga u predsezonu i sezonu na kraju treninga ili u krug za trup. Lakša varijanta: savijena koljena i ruke uz tijelo; teža: noge bliže podu ili lagano ljuljanje u istom položaju (hollow rock). Ako osjetiš bol u donjim leđima ili štipanje u preponi, savij koljena i podigni noge više (kraća poluga manje opterećuje pregibače kuka) ili prekini.",
