   "sets": 3,
   "reps": 10,
   "sec": 30,
   "rest": 45,
   "kg": 0,
   "sides": true,
   "feel": "Kosi trbušni mišići i cijeli trup koji se opire okretanju",
   "steps": [
    "Zaveži elastično uže za kavez u visini prsa i stani bočno uz njega, toliko daleko da uže bude napeto već u početnom položaju.",
    "Stopala postavi u širini kukova, lagano savij koljena i objema rukama uhvati ručku (ili kraj užeta) ispred prsne kosti, s laktovima uz tijelo.",
    "Zategni trbuh i stražnjicu, pa uz izdah polako ispruži ruke ravno naprijed od sredine prsa.",
    "U ispruženom položaju zadrži 2–3 sekunde i ne dopusti da te uže okrene prema sidru.",
    "Polako vrati ručku do prsa, bez trzaja i bez naginjanja prema užetu.",
    "Odradi sva ponavljanja, pa se okreni i ponovi s drugom stranom tijela prema sidru."
   ],
   "mistakes": [
    "Trup se okreće prema sidru – jače zategni trbuh i drži prsni koš i zdjelicu okrenute ravno naprijed.",
    "Naginješ se u stranu od užeta – stoj uspravno, s težinom jednako raspoređenom na oba stopala.",
    "Ruke idu ukoso prema sidru – guraj ručku ravno ispred sredine prsa.",
    "Uže je prejako pa se cijelo tijelo trese – uzmi tanje uže ili stani bliže sidru.",
    "Zadržavaš dah – izdahni dok guraš i diši mirno tijekom izdržaja."
   ],
   "note": "Pallof press uči trup da se odupre okretanju, što ti treba kad u duelu primaš kontakt ili kad udaraš loptu, a zdjelica mora ostati stabilna. Radi ga u predsezoni i sezoni 2–3 puta tjedno, kao aktivaciju trupa prije treninga snage ili nakon treninga s loptom. Lakša varijanta: širi stav i tanje uže; teža: poluklek, stopala skupa ili dulji izdržaj (5 s). Ako osjetiš bol u leđima ili kuku, smanji otpor ili prekini.",
   "source": "https://www.acefitness.org/resources/everyone/exercise-library/332/standing-anti-rotation-press/",
   "sourceTitle": "Standing Anti-Rotation Press | Exercise Library | ACE",
